def choose_move(observation):
    x = 0
    y = 0
    if isinstance(observation, dict):
        pos = observation.get("self_position") or observation.get("position") or {}
        x = pos.get("x", 0)
        y = pos.get("y", 0)
    best_dx = 0
    best_dy = 0
    best_score = -10**9

    def score_move(nx, ny):
        s = 0
        obs = observation if isinstance(observation, dict) else {}
        grid_w = obs.get("grid_width", 0)
        grid_h = obs.get("grid_height", 0)

        if grid_w and grid_h:
            if not (0 <= nx < grid_w and 0 <= ny < grid_h):
                return -10**6

        opp = obs.get("opponent_position") or {}
        ox = opp.get("x", nx)
        oy = opp.get("y", ny)
        dx = nx - ox
        dy = ny - oy
        s -= abs(dx) + abs(dy)

        res = obs.get("resources") or []
        if isinstance(res, list) and res:
            rx = None
            ry = None
            best_d = 10**9
            for r in res:
                rx = r.get("x", rx)
                ry = r.get("y", ry)
                if rx is None or ry is None:
                    continue
                d = abs(rx - nx) + abs(ry - ny)
                if d < best_d:
                    best_d = d
            if best_d < 10**9:
                s -= max(0, 5 - best_d)

        obs_list = obs.get("obstacles") or []
        if isinstance(obs_list, list):
            for ob in obs_list:
                bx = ob.get("x", nx)
                by = ob.get("y", ny)
                if nx == bx and ny == by:
                    s -= 5

        return s

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx = x + dx
            ny = y + dy
            sc = score_move(nx, ny)
            if sc > best_score:
                best_score = sc
                best_dx = dx
                best_dy = dy

    if best_score == -10**9:
        best_dx, best_dy = 0, 0

    return [best_dx, best_dy]
